{
  "name": "Specim Aisa Kestrel 10 高光谱相机",
  "name_en": "Specim Aisa Kestrel 10 hyperspectral camera",
  "manufacturer": "Specim",
  "description": "这是一款高光谱成像相机，用于采集样品在多个波段上的图像数据，常用于材料表征、样品筛查、反射/辐射成像等实验。实验中通常需要根据光照条件和采集速度调节帧率、积分时间、快门状态，并可启用非均匀性校正以改善成像质量。",
  "description_en": "This is a hyperspectral imaging camera used to acquire image data across multiple spectral bands. It is commonly used in laboratory work such as material characterization, sample screening, and reflectance or radiance imaging. In use, the frame rate, integration time, and shutter state are adjusted to match illumination and acquisition conditions, and non-uniformity correction may be enabled to improve image quality.",
  "tag_hints": [
    "hyperspectral imaging",
    "spectral camera",
    "frame rate control",
    "integration time",
    "shutter control",
    "non-uniformity correction",
    "sample imaging"
  ],
  "actions": [
    {
      "action_name": "auto-frame_rate",
      "description": "获取/设置帧率",
      "description_en": "get/set frame rate"
    },
    {
      "action_name": "auto-frame_rate_min",
      "description": "获取最小帧率",
      "description_en": "get minimum frame rate"
    },
    {
      "action_name": "auto-frame_rate_max",
      "description": "获取最大帧率",
      "description_en": "get maximum frame rate"
    },
    {
      "action_name": "auto-shutter_open",
      "description": "获取/设置快门开启状态",
      "description_en": "get/set shutter open state"
    },
    {
      "action_name": "auto-shutter_latency",
      "description": "获取快门延迟",
      "description_en": "get shutter latency"
    },
    {
      "action_name": "auto-integration_time",
      "description": "获取/设置积分时间",
      "description_en": "get/set integration time"
    },
    {
      "action_name": "auto-integration_time_min",
      "description": "获取最小积分时间",
      "description_en": "get minimum integration time"
    },
    {
      "action_name": "auto-integration_time_max",
      "description": "获取最大积分时间",
      "description_en": "get maximum integration time"
    },
    {
      "action_name": "auto-nuc",
      "description": "获取/设置非均匀性校正（NUC）",
      "description_en": "get/set non-uniformity correction (NUC)"
    },
    {
      "action_name": "auto-notify",
      "description": "定义需要通知的属性",
      "description_en": "define the property to notify"
    }
  ]
}

